def _tile_size(size, limit, alignment):
    if size <= limit:
        return size
    tile = min(size, limit)
    tile -= tile % alignment
    while tile > 0 and size % tile != 0:
        tile -= alignment
    return tile if tile > 0 else size


def _neg_exp_kernel(w_ref, out_ref):
    out_ref[...] = (-jnp.exp(w_ref[...])).astype(jnp.bfloat16)


def _matmul_kernel(x_ref, w_ref, bias_ref, out_ref, acc_ref, *, nsteps):
    k_index = pl.program_id(1)

    @pl.when(k_index == 0)
    def _initialize():
        acc_ref[...] = jnp.broadcast_to(
            bias_ref[...].astype(jnp.float32), acc_ref.shape
        )

    acc_ref[...] += jnp.dot(
        x_ref[...], w_ref[...], preferred_element_type=jnp.float32
    )

    @pl.when(k_index == nsteps - 1)
    def _store():
        out_ref[...] = acc_ref[...].astype(out_ref.dtype)


def workload(x, w, b):
    k = x.shape[-1]
    kw, n = w.shape
    rows = x.size // k

    weight_row_tile = _tile_size(kw, 128, 8)
    negative_exp_w = pl.pallas_call(
        _neg_exp_kernel,
        out_shape=jax.ShapeDtypeStruct(w.shape, jnp.bfloat16),
        in_specs=[
            pl.BlockSpec(
                (weight_row_tile, n), lambda block_index: (block_index, 0)
            )
        ],
        out_specs=pl.BlockSpec(
            (weight_row_tile, n), lambda block_index: (block_index, 0)
        ),
        grid=(kw // weight_row_tile,),
    )(w)

    x2d = x.reshape((rows, k)).astype(jnp.bfloat16)
    row_tile = _tile_size(rows, 512, 8)
    k_tile = _tile_size(k, 512, 128)
    nsteps = k // k_tile

    result = pl.pallas_call(
        functools_partial_matmul(nsteps),
        out_shape=jax.ShapeDtypeStruct((rows, n), x.dtype),
        in_specs=[
            pl.BlockSpec(
                (row_tile, k_tile), lambda row_index, k_index: (row_index, k_index)
            ),
            pl.BlockSpec(
                (k_tile, n), lambda row_index, k_index: (k_index, 0)
            ),
            pl.BlockSpec((n,), lambda row_index, k_index: (0,)),
        ],
        out_specs=pl.BlockSpec(
            (row_tile, n), lambda row_index, k_index: (row_index, 0)
        ),
        scratch_shapes=[pltpu_vmem((row_tile, n))],
        grid=(rows // row_tile, nsteps),
    )(x2d, negative_exp_w, b)

    return result.reshape(x.shape[:-1] + (n,))


def functools_partial_matmul(nsteps):
    def kernel(x_ref, w_ref, bias_ref, out_ref, acc_ref):
        _matmul_kernel(
            x_ref, w_ref, bias_ref, out_ref, acc_ref, nsteps=nsteps
        )
    return kernel


def pltpu_vmem(shape):
    from jax.experimental.pallas import tpu as pltpu
    return pltpu.VMEM(shape, jnp.float32)

