    x_c = x2[:, :half]
    x_p = x2[:, half:]
    b_c2 = b_c.reshape((1, cols))
    b_p2 = b_p.reshape((1, cols))

    bm = _tile(rows, 512, 8)
    bk = _tile(half, 512, 128)
    bn = _tile(cols, 512, 128)

    def x_map(i, j, k):
        return (i, k)

    def w_map(i, j, k):
        return (k, j)

    def b_map(i, j, k):
        return (0, j)

    def o_map(i, j, k):
        return (i, j)

    grid_spec = pltpu.PrefetchScalarGridSpec(
        num_scalar_prefetch=0,
        grid=(rows // bm, cols // bn, half // bk),
        in_specs=(
            pl.BlockSpec((bm, bk), x_map),
            pl.BlockSpec((bm, bk), x_map),
            pl.BlockSpec((bk, bn), w_map),
            pl.BlockSpec((bk, bn), w_map),
            pl.BlockSpec((1, bn), b_map),
            pl.BlockSpec((1, bn), b_map),
        ),
        out_specs=(
            pl.BlockSpec((bm, bn), o_map),
            pl.BlockSpec((bm, bn), o_map),
        ),
        scratch_shapes=(
            pltpu.VMEM((bm, bn), jnp.float32),
            pltpu.VMEM((bm, bn), jnp.float32),
        ),
    )

    out_c, out_p = pl.pallas_call(
        _kernel,
        grid_spec=grid_spec,
        out_shape=(
            jax.ShapeDtypeStruct((rows, cols), x.dtype),
            jax.ShapeDtypeStruct((rows, cols), x.dtype),
        ),
        compiler_params=pltpu.CompilerParams(
            dimension_semantics=('parallel', 'parallel', 'arbitrary')
        ),
    )(x_c, x_p, w_c, w_p, b_c2, b_p2)

    output_shape = leading_shape + (cols,)
    return out_c.reshape(output_shape), out_p.reshape(output_shape)

